// Convert hex char to binary form. Requires that c be a hex char.
static unsigned long greis_hex2bin(char c)
{
    if (('a' <= c) && ('f' >= c)) {
        c = c + 10 - 'a';
    } else if (('A' <= c) && ('F' >= c)) {
        c = c + 10 - 'A';
    } else if (('0' <= c) && ('9' >= c)) {
        c -= '0';
    }
    // FIXME: No error handling?

    return c;
}

